import local.thor.bilichannels.*;import org.json.*;import java.util.*;
public class SearchGestureTest {
 static int cases;static void check(boolean b,String s){cases++;if(!b)throw new AssertionError(s);}
 static Video video(int n){return new Video(String.format("BV%010d",n),"video "+n,"","",n,n,60,false);}
 public static void main(String[] args)throws Exception{
  SearchPager model=new SearchPager();model.reset("汽车");int stale=model.begin();model.reset("掌机");check(!model.accept(stale,new SearchPager.Page(Arrays.asList(video(1)),1,2,true)),"old query ignored");
  for(int page=1;page<=10;page++){int token=model.begin();check(model.begin()==-1,"one inflight page");List<Video> rows=new ArrayList<>();for(int n=(page-1)*20;n<page*20;n++)rows.add(video(n));if(page>1)rows.add(video(0));check(model.accept(token,new SearchPager.Page(rows,page,10,page<10)),"page accepted");check(model.items.size()==page*20,"append and deduplicate without limit");}
  check(!model.more&&model.begin()==-1,"server final page");model.reset("汽车");int token=model.begin();model.fail(token,"offline");check(model.page==0&&model.items.isEmpty()&&model.more&&!model.loading,"failure can retry same page");token=model.begin();model.accept(token,new SearchPager.Page(Arrays.asList(video(1)),1,-1,true));token=model.begin();check(!model.accept(token,new SearchPager.Page(Arrays.asList(video(1)),2,-1,true))&&!model.error.isEmpty()&&model.page==1,"repeated platform page is retryable, not false end");
  JSONObject row=new JSONObject().put("bvid","BV1234567890").put("title","<em>汽车</em>");JSONObject data=new JSONObject().put("page",1).put("numPages",8).put("result",new JSONArray().put(row));SearchPager.Page page=ApiModels.searchPage(data,1);check(page.items.size()==1&&page.more&&page.totalPages==8,"short filtered page keeps server more");data.put("page",8);check(!ApiModels.searchPage(data,8).more,"known last page");data.remove("numPages");data.put("result",new JSONArray());check(!ApiModels.searchPage(data,8).more,"empty unknown total ends");
  check(PlaybackGesture.classify(10,300,1,-50,8)==PlaybackGesture.BRIGHTNESS,"left brightness");check(PlaybackGesture.classify(290,300,1,-50,8)==PlaybackGesture.VOLUME,"right volume");check(PlaybackGesture.classify(150,300,50,1,8)==PlaybackGesture.SEEK,"center horizontal seek");check(PlaybackGesture.classify(150,300,1,-50,8)==0,"center vertical no accidental volume");check(PlaybackGesture.classify(10,300,1,1,8)==0,"touch slop");check(PlaybackGesture.level(.5f,-1000,300)==1&&PlaybackGesture.level(.5f,1000,300)==0,"level clamp");check(PlaybackGesture.seek(5000,-500,300,10000)==0&&PlaybackGesture.seek(5000,500,300,10000)==9999,"seek clamp");
  for(float x:new float[]{0,5,25,90,150,210,275,295,300}){check(PlaybackGesture.classify(x,300,50,2,8)==PlaybackGesture.SEEK,"horizontal seek starts across picture at "+x);check(PlaybackGesture.classify(x,300,-50,2,8)==PlaybackGesture.SEEK,"reverse seek starts across picture at "+x);}check(PlaybackGesture.classify(25,300,10,45,8)==PlaybackGesture.BRIGHTNESS,"vertical left still brightness");check(PlaybackGesture.classify(275,300,10,45,8)==PlaybackGesture.VOLUME,"vertical right still volume");check(PlaybackGesture.classify(25,300,15,15,8)==0,"diagonal waits for intent");
  System.out.println("PASS: "+cases+" pagination and gesture cases");
 }
}
